import{C as o}from"./chunks/ContainerGuide.CD6rK92e.js";import{o as a,a as s,d as e,H as d}from"./chunks/framework.MWxrmMMs.js";import"./chunks/theme.CZQCAeZ1.js";const u=JSON.parse('{"title":"Консольная версия","description":"stuzhik-cli: Stuzhik без окна для серверов Minecraft на Linux. Один файл без зависимостей, пакеты .deb и .rpm, служба systemd, контейнер, бэкапы и обновление модпака из терминала.","frontmatter":{"platform":"Linux","description":"stuzhik-cli: Stuzhik без окна для серверов Minecraft на Linux. Один файл без зависимостей, пакеты .deb и .rpm, служба systemd, контейнер, бэкапы и обновление модпака из терминала.","head":[["meta",{"name":"keywords","content":"stuzhik-cli, сервер minecraft linux, minecraft сервер systemd, сервер из модпака, minecraft сервер docker, raspberry pi minecraft сервер"}]]},"headers":[],"relativePath":"guide/cli.md","filePath":"guide/cli.md"}'),c={name:"guide/cli.md"},h=Object.assign(c,{setup(l){return(r,t)=>(a(),s("div",null,[t[0]||(t[0]=e(`<h1 id="консольная-версия" tabindex="-1">Консольная версия <a class="header-anchor" href="#консольная-версия" aria-label="Permalink to &quot;Консольная версия&quot;">​</a></h1><p><code>stuzhik-cli</code> это Stuzhik без окна: серверы Minecraft из терминала, службой systemd или в контейнере. Это один файл без зависимостей для любого Linux на x86_64 и на ARM (aarch64: Raspberry Pi 4 и новее, ARM-серверы).</p><p>Данные у него те же, что у приложения с окном: сервер, созданный в окне, запускается из терминала, и наоборот.</p><h2 id="установка" tabindex="-1">Установка <a class="header-anchor" href="#установка" aria-label="Permalink to &quot;Установка&quot;">​</a></h2><p>Файлы для x86_64 и ARM и команды, которые их скачивают и ставят, на <a href="/download.html#cli">странице скачивания</a>. Для ARM в именах стоит <code>arm64</code> или <code>aarch64</code> вместо <code>amd64</code> и <code>x86_64</code>.</p><table tabindex="0"><thead><tr><th>Система</th><th>Как поставить</th></tr></thead><tbody><tr><td>Debian, Ubuntu, Mint</td><td><code>sudo apt install ./stuzhik-cli_*_amd64.deb</code></td></tr><tr><td>Fedora, RHEL, Alma, Rocky</td><td><code>sudo dnf install ./stuzhik-cli-*.x86_64.rpm</code></td></tr><tr><td>openSUSE</td><td><code>sudo rpm -i ./stuzhik-cli-*.x86_64.rpm</code></td></tr><tr><td>Arch и любая другая</td><td><code>tar xzf stuzhik-cli-*-x86_64-linux.tar.gz</code>, затем <code>sudo install -m 0755 stuzhik-cli-*-x86_64-linux/stuzhik-cli /usr/local/bin/</code></td></tr></tbody></table><p>Пакеты пока не подписаны: dnf предупредит «skipped OpenPGP checks», это ожидаемо. Сверить файлы можно по <a href="/download.html#checksums">SHA256SUMS</a>: <code>sha256sum -c SHA256SUMS --ignore-missing</code>.</p><p>Java для сервера лаунчер скачивает сам. Она собрана под glibc: на Alpine и других системах на musl нужен пакет <code>gcompat</code> или своя Java в настройках сборки.</p><h2 id="быстрыи-старт" tabindex="-1">Быстрый старт <a class="header-anchor" href="#быстрыи-старт" aria-label="Permalink to &quot;Быстрый старт&quot;">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#B392F0;">stuzhik-cli</span><span style="color:#9ECBFF;"> create</span><span style="color:#9ECBFF;"> &quot;Мой сервер&quot;</span><span style="color:#79B8FF;"> --mc</span><span style="color:#79B8FF;"> 1.21.1</span><span style="color:#79B8FF;"> --loader</span><span style="color:#9ECBFF;"> fabric</span><span style="color:#79B8FF;"> --accept-eula</span></span>
<span class="line"><span style="color:#B392F0;">stuzhik-cli</span><span style="color:#9ECBFF;"> run</span><span style="color:#9ECBFF;"> &quot;Мой сервер&quot;</span></span></code></pre></div><p>Консоль сервера открыта в этом же терминале: команды набираются как обычно. Ctrl+C останавливает сервер командой <code>stop</code> (мир сохраняется), второй Ctrl+C завершает его сразу.</p><p>Сборку можно назвать по id, по имени или по их началу.</p><h2 id="сервер-из-модпака" tabindex="-1">Сервер из модпака <a class="header-anchor" href="#сервер-из-модпака" aria-label="Permalink to &quot;Сервер из модпака&quot;">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#B392F0;">stuzhik-cli</span><span style="color:#9ECBFF;"> create</span><span style="color:#9ECBFF;"> &quot;Пак&quot;</span><span style="color:#79B8FF;"> --modpack</span><span style="color:#9ECBFF;"> ./pack.mrpack</span><span style="color:#79B8FF;"> --accept-eula</span></span></code></pre></div><p>Модпак берётся из файла (<code>.mrpack</code>, <code>.zip</code> CurseForge, <code>.stzhk</code>), по адресу на modrinth.com, как <code>modrinth:&lt;проект&gt;[@&lt;версия&gt;]</code> или <code>curseforge:&lt;id проекта&gt;[@&lt;id файла&gt;]</code>. Ставится сразу сервером, без клиентских файлов игры, а клиентские моды пака отключаются. Моды, про которые не удалось узнать, нужны ли они серверу, перечисляются в конце, чтобы их можно было проверить руками.</p><p>Обновить пак:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#B392F0;">stuzhik-cli</span><span style="color:#9ECBFF;"> update</span><span style="color:#9ECBFF;"> &quot;Пак&quot;</span></span></code></pre></div><p>Сначала видно, что изменится: какие моды добавятся, обновятся и уйдут. Применяется после «да». Перед обновлением делается бэкап (<code>--no-backup</code>: без него), уже лежащие конфиги остаются (<code>--overwrite-configs</code>: заменить их конфигами пака), <code>--to</code> выбирает версию. Обновление на версию пака для другой версии игры делается только в окне: там у него есть откат.</p><h2 id="команды" tabindex="-1">Команды <a class="header-anchor" href="#команды" aria-label="Permalink to &quot;Команды&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Команда</th><th>Что делает</th></tr></thead><tbody><tr><td><code>list</code>, <code>info &lt;сборка&gt;</code></td><td>сборки и подробности (<code>--json</code> для скриптов)</td></tr><tr><td><code>create &lt;имя&gt; --mc &lt;версия&gt; [--loader …] [--port] [--memory МБ] [--accept-eula]</code></td><td>создать и установить сервер</td></tr><tr><td><code>create &lt;имя&gt; --modpack &lt;пак&gt;</code></td><td>сервер из модпака</td></tr><tr><td><code>run &lt;сборка&gt;</code></td><td>запустить в этом терминале</td></tr><tr><td><code>console &lt;сборка&gt;</code></td><td>консоль сервера, который <code>run</code> держит в другом терминале или службой</td></tr><tr><td><code>tui</code></td><td>экран в терминале: сборки, консоль сервера и его server.properties</td></tr><tr><td><code>update &lt;сборка&gt;</code></td><td>обновить модпак сборки, с предпросмотром</td></tr><tr><td><code>backup &lt;сборка&gt;</code>, <code>backups &lt;сборка&gt;</code>, <code>restore &lt;бэкап&gt; [--worlds]</code></td><td>бэкапы</td></tr><tr><td><code>eula &lt;сборка&gt; [--accept]</code>, <code>props &lt;сборка&gt; [key=value…]</code></td><td>EULA и server.properties</td></tr><tr><td><code>analyze &lt;сборка или файл лога&gt;</code></td><td>разбор логов: проблемы и что делать</td></tr><tr><td><code>service &lt;сборка&gt; [--install] [--system]</code></td><td>служба systemd</td></tr><tr><td><code>paths</code></td><td>где лежат данные</td></tr></tbody></table><p>Загрузчики: <code>vanilla</code>, <code>fabric</code>, <code>quilt</code>, <code>forge</code>, <code>neoforge</code>. Все команды и опции: <code>stuzhik-cli --help</code>.</p><h2 id="служба-systemd" tabindex="-1">Служба systemd <a class="header-anchor" href="#служба-systemd" aria-label="Permalink to &quot;Служба systemd&quot;">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#B392F0;">stuzhik-cli</span><span style="color:#9ECBFF;"> service</span><span style="color:#9ECBFF;"> &quot;Мой сервер&quot;</span><span style="color:#79B8FF;"> --install</span></span>
<span class="line"><span style="color:#B392F0;">systemctl</span><span style="color:#79B8FF;"> --user</span><span style="color:#9ECBFF;"> daemon-reload</span></span>
<span class="line"><span style="color:#B392F0;">systemctl</span><span style="color:#79B8FF;"> --user</span><span style="color:#9ECBFF;"> enable</span><span style="color:#79B8FF;"> --now</span><span style="color:#9ECBFF;"> stuzhik-</span><span style="color:#F97583;">&lt;</span><span style="color:#9ECBFF;">им</span><span style="color:#E1E4E8;">я</span><span style="color:#F97583;">&gt;</span></span>
<span class="line"><span style="color:#B392F0;">loginctl</span><span style="color:#9ECBFF;"> enable-linger</span><span style="color:#E1E4E8;"> $USER</span></span></code></pre></div><p>Точное имя службы печатает первая команда. <code>enable-linger</code> нужен, чтобы сервер работал без входа в систему; <code>--system</code> пишет системную службу (нужен root), она работает от имени текущего пользователя.</p><p><code>systemctl stop</code> сохраняет мир: сервер получает <code>stop</code>, а не обрывается. Упавший сервер перезапускается сам, а ошибка настройки (например, не принята EULA) не перезапускается, чтобы служба не крутилась вхолостую.</p><p>Консоль работающей службы: <code>stuzhik-cli console &quot;Мой сервер&quot;</code>: последние строки вывода, потом живые, и ваши команды уходят серверу. Ctrl+C только отключает консоль, сервер работает дальше.</p><h2 id="контеинер" tabindex="-1">Контейнер <a class="header-anchor" href="#контеинер" aria-label="Permalink to &quot;Контейнер&quot;">​</a></h2><p>Образ собирается из архива консольной версии, на Podman и на Docker одинаково. Данные сервера живут в томе <code>stuzhik</code> и переживают пересоздание контейнера.</p>`,28)),d(o),t[1]||(t[1]=e('<p>Отключиться от консоли и оставить сервер работать: Ctrl+P, затем Ctrl+Q. <code>stop</code> (или <code>podman stop mc</code>, <code>docker stop mc</code>) сохраняет мир: на это контейнеру дано 120 секунд.</p><h2 id="данные" tabindex="-1">Данные <a class="header-anchor" href="#данные" aria-label="Permalink to &quot;Данные&quot;">​</a></h2><p>По умолчанию это та же папка, что у приложения с окном. Другая: <code>--data-dir /srv/stuzhik</code> или переменная <code>STUZHIK_DATA=/srv/stuzhik</code>.</p><p>Пока команда работает, окно не переносит папку данных на другой диск и говорит почему, а команда, запущенная посреди переноса, ждать не станет и попросит дождаться его конца.</p><h2 id="язык-и-коды-выхода" tabindex="-1">Язык и коды выхода <a class="header-anchor" href="#язык-и-коды-выхода" aria-label="Permalink to &quot;Язык и коды выхода&quot;">​</a></h2><p>Сообщения выводятся на языке системы; <code>STUZHIK_LANG=ru</code> или <code>en</code> задают его явно (у сервера часто стоит <code>C</code>, тогда русский).</p><p>Коды выхода: 0: готово, 1: сервер упал, 2: отказ (сборки нет, EULA не принята, неверная опция), 3: <code>analyze</code> нашёл критичную проблему. На них опирается служба: код 2 не перезапускается.</p>',7))]))}});export{u as __pageData,h as default};
